INSERT INTO "user_profiles" ("display_text", "user_id", "birthday", "gender", "hometown", "location", "headline", "biography", "phone", "website", "social_links", "avatar_media_id", "cv_bytes", "cv_filename", "cv_mime_type", "cv_sha256", "cv_text", "cv_context", "cv_status", "cv_error", "cv_simulated", "cv_updated_at", "created_at") VALUES ('{"headline": {"source": "Investigations supervisor \u00b7 Pacific Ridge Police Department", "en": "Investigations supervisor \u00b7 Pacific Ridge Police Department", "es": "Supervisor de investigaciones \u00b7 Pacific Ridge Police Department"}, "biography": {"source": "Coordinates incident review, evidence handovers and field documentation for the investigations team. Twelve years of experience in patrol and investigative support, with a focus on clear records, chain of custody and communication between shifts.", "en": "Coordinates incident review, evidence handovers and field documentation for the investigations team. Twelve years of experience in patrol and investigative support, with a focus on clear records, chain of custody and communication between shifts.", "es": "Coordina la revisi\u00f3n de incidentes, la entrega de evidencias y la documentaci\u00f3n de campo del equipo de investigaciones. Cuenta con doce a\u00f1os de experiencia en patrullaje y apoyo investigativo, con \u00e9nfasis en expedientes claros, cadena de custodia y comunicaci\u00f3n entre turnos."}, "gender": {"source": "male", "en": "Male", "es": "Masculino"}, "social_links": {"source": [{"label": "Professional profile", "url": "https://pacific-ridge.example.com/team/alex-rivera"}, {"label": "Work group", "url": "https://pacific-ridge.example.com/team"}], "en": [{"label": "Professional profile", "url": "https://pacific-ridge.example.com/team/alex-rivera"}, {"label": "Work group", "url": "https://pacific-ridge.example.com/team"}], "es": [{"label": "Perfil profesional", "url": "https://pacific-ridge.example.com/team/alex-rivera"}, {"label": "Grupo de trabajo", "url": "https://pacific-ridge.example.com/team"}]}}', '6b70a3aa0e7b52348245a923d31bd2ec', '1990-07-18', 'male', 'Fresno, California', 'San Diego, California', 'Investigations supervisor · Pacific Ridge Police Department', 'Coordinates incident review, evidence handovers and field documentation for the investigations team. Twelve years of experience in patrol and investigative support, with a focus on clear records, chain of custody and communication between shifts.', '+1 619 555 0101', 'https://pacific-ridge.example.com', '[{"label": "Professional profile", "url": "https://pacific-ridge.example.com/team/alex-rivera"}, {"label": "Work group", "url": "https://pacific-ridge.example.com/team"}]', '2e17e87026405911b419935a3dbabf23', NULL, NULL, NULL, NULL, NULL, NULL, 'empty', NULL, FALSE, NULL, '2026-11-04 14:14:56');
INSERT INTO "user_profiles" ("display_text", "user_id", "birthday", "gender", "hometown", "location", "headline", "biography", "phone", "website", "social_links", "avatar_media_id", "cv_bytes", "cv_filename", "cv_mime_type", "cv_sha256", "cv_text", "cv_context", "cv_status", "cv_error", "cv_simulated", "cv_updated_at", "created_at") VALUES ('{"headline": {"source": "Crime scene investigator \u00b7 Pacific Ridge Police Department", "en": "Crime scene investigator \u00b7 Pacific Ridge Police Department", "es": "Investigadora de escenas del delito \u00b7 Pacific Ridge Police Department"}, "biography": {"source": "Documents incident scenes, prepares photographic records and coordinates evidence collection with investigators. Specializes in scene organization, traceable observations and consistent handovers between field and laboratory teams.", "en": "Documents incident scenes, prepares photographic records and coordinates evidence collection with investigators. Specializes in scene organization, traceable observations and consistent handovers between field and laboratory teams.", "es": "Documenta las escenas de incidentes, prepara registros fotogr\u00e1ficos y coordina la recogida de evidencias con los investigadores. Se especializa en la organizaci\u00f3n de escenas, observaciones trazables y entregas consistentes entre los equipos de campo y laboratorio."}, "gender": {"source": "female", "en": "Female", "es": "Femenino"}, "social_links": {"source": [{"label": "Professional profile", "url": "https://pacific-ridge.example.com/team/maya-johnson"}, {"label": "Work group", "url": "https://pacific-ridge.example.com/team"}], "en": [{"label": "Professional profile", "url": "https://pacific-ridge.example.com/team/maya-johnson"}, {"label": "Work group", "url": "https://pacific-ridge.example.com/team"}], "es": [{"label": "Perfil profesional", "url": "https://pacific-ridge.example.com/team/maya-johnson"}, {"label": "Grupo de trabajo", "url": "https://pacific-ridge.example.com/team"}]}}', '002698d65b515f23a6b78f9ac69767a8', '1992-02-11', 'female', 'Oakland, California', 'San Diego, California', 'Crime scene investigator · Pacific Ridge Police Department', 'Documents incident scenes, prepares photographic records and coordinates evidence collection with investigators. Specializes in scene organization, traceable observations and consistent handovers between field and laboratory teams.', '+1 619 555 0102', 'https://pacific-ridge.example.com', '[{"label": "Professional profile", "url": "https://pacific-ridge.example.com/team/maya-johnson"}, {"label": "Work group", "url": "https://pacific-ridge.example.com/team"}]', '927fee29da335045b1cf6699359d4711', NULL, NULL, NULL, NULL, NULL, NULL, 'empty', NULL, FALSE, NULL, '2026-11-04 14:14:56');
INSERT INTO "user_profiles" ("display_text", "user_id", "birthday", "gender", "hometown", "location", "headline", "biography", "phone", "website", "social_links", "avatar_media_id", "cv_bytes", "cv_filename", "cv_mime_type", "cv_sha256", "cv_text", "cv_context", "cv_status", "cv_error", "cv_simulated", "cv_updated_at", "created_at") VALUES ('{"headline": {"source": "Evidence and records technician \u00b7 Pacific Ridge Police Department", "en": "Evidence and records technician \u00b7 Pacific Ridge Police Department", "es": "T\u00e9cnico de evidencias y expedientes \u00b7 Pacific Ridge Police Department"}, "biography": {"source": "Maintains the evidence inventory, verifies intake records and prepares material for authorized case review. Supports investigators with organized attachments, equipment checks and accurate records of every evidence transfer.", "en": "Maintains the evidence inventory, verifies intake records and prepares material for authorized case review. Supports investigators with organized attachments, equipment checks and accurate records of every evidence transfer.", "es": "Mantiene el inventario de evidencias, verifica los registros de ingreso y prepara material para la revisi\u00f3n autorizada de casos. Apoya a los investigadores con adjuntos organizados, comprobaciones de equipos y registros precisos de cada traslado de evidencias."}, "gender": {"source": "male", "en": "Male", "es": "Masculino"}, "social_links": {"source": [{"label": "Professional profile", "url": "https://pacific-ridge.example.com/team/daniel-kim"}, {"label": "Work group", "url": "https://pacific-ridge.example.com/team"}], "en": [{"label": "Professional profile", "url": "https://pacific-ridge.example.com/team/daniel-kim"}, {"label": "Work group", "url": "https://pacific-ridge.example.com/team"}], "es": [{"label": "Perfil profesional", "url": "https://pacific-ridge.example.com/team/daniel-kim"}, {"label": "Grupo de trabajo", "url": "https://pacific-ridge.example.com/team"}]}}', '9e1da78288e05d07b552c5303c08721c', '1994-11-09', 'male', 'San Jose, California', 'San Diego, California', 'Evidence and records technician · Pacific Ridge Police Department', 'Maintains the evidence inventory, verifies intake records and prepares material for authorized case review. Supports investigators with organized attachments, equipment checks and accurate records of every evidence transfer.', '+1 619 555 0103', 'https://pacific-ridge.example.com', '[{"label": "Professional profile", "url": "https://pacific-ridge.example.com/team/daniel-kim"}, {"label": "Work group", "url": "https://pacific-ridge.example.com/team"}]', '3ce5cf2c15d1540882ef55c98826187f', NULL, NULL, NULL, NULL, NULL, NULL, 'empty', NULL, FALSE, NULL, '2026-11-04 14:14:56');
INSERT INTO "user_profiles" ("display_text", "user_id", "birthday", "gender", "hometown", "location", "headline", "biography", "phone", "website", "social_links", "avatar_media_id", "cv_bytes", "cv_filename", "cv_mime_type", "cv_sha256", "cv_text", "cv_context", "cv_status", "cv_error", "cv_simulated", "cv_updated_at", "created_at") VALUES ('{"headline": {"source": "Registered nurse and unit coordinator \u00b7 California Valley Medical Center", "en": "Registered nurse and unit coordinator \u00b7 California Valley Medical Center", "es": "Enfermera y coordinadora de unidad \u00b7 California Valley Medical Center"}, "biography": {"source": "Coordinates the nursing shift, patient handovers and follow-up documentation. Fifteen years of experience in inpatient care, with an emphasis on organized observations, medication-record verification and clear communication with the care team.", "en": "Coordinates the nursing shift, patient handovers and follow-up documentation. Fifteen years of experience in inpatient care, with an emphasis on organized observations, medication-record verification and clear communication with the care team.", "es": "Coordina el turno de enfermer\u00eda, las entregas de pacientes y la documentaci\u00f3n de seguimiento. Cuenta con quince a\u00f1os de experiencia en hospitalizaci\u00f3n, con \u00e9nfasis en observaciones organizadas, verificaci\u00f3n de registros de medicaci\u00f3n y comunicaci\u00f3n clara con el equipo asistencial."}, "gender": {"source": "female", "en": "Female", "es": "Femenino"}, "social_links": {"source": [{"label": "Professional profile", "url": "https://california-valley.example.com/team/elena-marquez"}, {"label": "Work group", "url": "https://california-valley.example.com/team"}], "en": [{"label": "Professional profile", "url": "https://california-valley.example.com/team/elena-marquez"}, {"label": "Work group", "url": "https://california-valley.example.com/team"}], "es": [{"label": "Perfil profesional", "url": "https://california-valley.example.com/team/elena-marquez"}, {"label": "Grupo de trabajo", "url": "https://california-valley.example.com/team"}]}}', '484b780027455aa4aa0f3d3ed603acf6', '1988-04-24', 'female', 'San Jose, California', 'Sacramento, California', 'Registered nurse and unit coordinator · California Valley Medical Center', 'Coordinates the nursing shift, patient handovers and follow-up documentation. Fifteen years of experience in inpatient care, with an emphasis on organized observations, medication-record verification and clear communication with the care team.', '+1 916 555 0104', 'https://california-valley.example.com', '[{"label": "Professional profile", "url": "https://california-valley.example.com/team/elena-marquez"}, {"label": "Work group", "url": "https://california-valley.example.com/team"}]', '68d1933a53435ad49bb4c4dce72f1fe2', NULL, NULL, NULL, NULL, NULL, NULL, 'empty', NULL, FALSE, NULL, '2026-11-04 14:14:57');
INSERT INTO "user_profiles" ("display_text", "user_id", "birthday", "gender", "hometown", "location", "headline", "biography", "phone", "website", "social_links", "avatar_media_id", "cv_bytes", "cv_filename", "cv_mime_type", "cv_sha256", "cv_text", "cv_context", "cv_status", "cv_error", "cv_simulated", "cv_updated_at", "created_at") VALUES ('{"headline": {"source": "Registered nurse, inpatient care \u00b7 California Valley Medical Center", "en": "Registered nurse, inpatient care \u00b7 California Valley Medical Center", "es": "Enfermero de hospitalizaci\u00f3n \u00b7 California Valley Medical Center"}, "biography": {"source": "Provides bedside nursing support and keeps patient observations and shift notes up to date. Works with the unit coordinator to prepare care handovers, organize supplies and document completed tasks for the next team.", "en": "Provides bedside nursing support and keeps patient observations and shift notes up to date. Works with the unit coordinator to prepare care handovers, organize supplies and document completed tasks for the next team.", "es": "Brinda apoyo de enfermer\u00eda junto a la cama del paciente y mantiene actualizadas las observaciones y notas de turno. Trabaja con la coordinaci\u00f3n de unidad para preparar entregas de atenci\u00f3n, organizar suministros y documentar las tareas completadas para el siguiente equipo."}, "gender": {"source": "male", "en": "Male", "es": "Masculino"}, "social_links": {"source": [{"label": "Professional profile", "url": "https://california-valley.example.com/team/mateo-rios"}, {"label": "Work group", "url": "https://california-valley.example.com/team"}], "en": [{"label": "Professional profile", "url": "https://california-valley.example.com/team/mateo-rios"}, {"label": "Work group", "url": "https://california-valley.example.com/team"}], "es": [{"label": "Perfil profesional", "url": "https://california-valley.example.com/team/mateo-rios"}, {"label": "Grupo de trabajo", "url": "https://california-valley.example.com/team"}]}}', '9467affefe045ed8ae5c4d4bb7c5ac23', '1993-09-16', 'male', 'Fresno, California', 'Sacramento, California', 'Registered nurse, inpatient care · California Valley Medical Center', 'Provides bedside nursing support and keeps patient observations and shift notes up to date. Works with the unit coordinator to prepare care handovers, organize supplies and document completed tasks for the next team.', '+1 916 555 0105', 'https://california-valley.example.com', '[{"label": "Professional profile", "url": "https://california-valley.example.com/team/mateo-rios"}, {"label": "Work group", "url": "https://california-valley.example.com/team"}]', '771cf8dbd0e95b14ab85e2059493492c', NULL, NULL, NULL, NULL, NULL, NULL, 'empty', NULL, FALSE, NULL, '2026-11-04 14:14:57');
